/**
 * The capture artifact.
 *
 * One envelope for every capture, whatever the transport. The rule that shaped it: the probe
 * records, Node computes. `report` holds the raw tables and is the only part a re-score reads;
 * `summaries` and `verdicts` are derived and may be regenerated by a later package version. An
 * artifact is stored whole — trimming `events` leaves the headline number plausible while the
 * fidelity verdict silently flips to false.
 */

import type {
  InputTransportId,
  MeasurementChannelId,
  InstrumentId,
  PageGeometry,
} from './transport.js';
import type { ScenarioKind } from './scenario.js';

export interface ArtifactSchema {
  readonly name: 'perf-rig.capture';
  readonly version: 1;
  /** Which probe wrote `report`, and its row schema version. */
  readonly probe: { readonly id: string; readonly version: number };
}

/**
 * Every guard the harness ran, with its outcome. A list, not a score. `unrecorded` means the guard
 * did not apply to this transport; a reader treats it as unknown, never as a pass.
 */
export interface TrustEntry {
  readonly name: GuardId;
  readonly state: 'verified' | 'failed' | 'unrecorded' | 'not-applicable';
  readonly detail?: string;
}

export type GuardId =
  | 'served-build-identity'
  | 'build-seams-present'
  | 'refused-build-variant'
  | 'page-identity-nonce'
  | 'route-hydrated'
  | 'hit-test-surface'
  | 'committed-mode'
  | 'dimension-observed'
  | 'painted-output'
  | 'runtime-user-agent'
  | 'packaged-origin'
  | 'entry-module-match'
  | 'service-worker-blocked'
  | 'orientation-followed'
  | 'host-quiet'
  | 'instrument-restored'
  | 'gesture-plan'
  | 'gesture-repeats'
  | 'prime-verified'
  | 'measured-action-proof'
  | 'input-fidelity'
  | 'refresh-regime';

export interface Provenance {
  /** Commit the served build was produced from, read from the build-time stamp; never capture-time HEAD. */
  readonly productCommit: string | null;
  readonly buildEntry: string | null;
  readonly buildDigest: string | null;
  readonly dirty: boolean | null;
  readonly harnessVersion: string;
  /** Hash over the modules that decide what this capture measures. */
  readonly instrumentFingerprint: string;
  readonly capturedAt: string;
  /** Nonce the page echoed back, proving these rows belong to this run. */
  readonly nonce: string | null;
  readonly pageIdentity: 'proved' | 'unprovable';
}

export interface CaptureArtifact<Report = RawReport, Summaries = unknown> {
  readonly schema: ArtifactSchema;
  readonly label: string;
  readonly target: string;
  readonly scenario: { readonly kind: ScenarioKind; readonly id: string };
  readonly transport: InputTransportId;
  readonly channel: MeasurementChannelId;
  readonly captureRuntime: string;
  readonly nativeApp: boolean;
  readonly appUrl: string;
  readonly nativePackage?: string;
  readonly provenance: Provenance;
  readonly device: {
    readonly model?: string;
    readonly os?: string;
    readonly identifier: '[redacted]' | null;
  };
  readonly geometry: PageGeometry;
  /** Observed values of every app dimension, read back from the page after setup. */
  readonly dimensions: Readonly<Record<string, string>>;
  readonly instruments: readonly {
    readonly id: InstrumentId;
    readonly files: readonly string[];
    readonly summary?: unknown;
  }[];
  readonly trust: readonly TrustEntry[];
  /** Raw tables. The re-score reads only this. */
  readonly report: Report;
  /** Derived at capture time by the package version in `provenance.harnessVersion`. */
  readonly summaries?: Summaries;
  readonly verdicts?: Readonly<Record<string, Verdict>>;
  /** Scenario-specific evidence (gesture plan id, repeats, refills, measured-action proofs). */
  readonly evidence: Readonly<Record<string, unknown>>;
}

export interface RawReport {
  readonly meta: {
    readonly url: string;
    readonly userAgent: string;
    readonly dpr: number;
    readonly timeOriginUnixMs: number;
    readonly measureNames: readonly string[];
    readonly counts: Readonly<Record<string, number>>;
  };
  readonly frames: readonly (readonly number[])[];
  readonly events: readonly (readonly number[])[];
  readonly measures: readonly (readonly number[])[];
  readonly history?: readonly (readonly number[])[];
  readonly phases?: readonly unknown[];
}

export interface Verdict {
  readonly passed: boolean;
  readonly reasons: readonly string[];
}

/** Layout of an output directory: `<root>/<timestamp>-<label>/` unless a campaign names the path. */
export declare function artifactDirectory(root: string, label: string, now?: Date): string;

export declare function readArtifact(path: string): Promise<CaptureArtifact>;
export declare function writeArtifact(path: string, artifact: CaptureArtifact): Promise<void>;
